L["1 paladin in your group"] = "1 paladino no seu grupo"
L["1 player has their own blessing"] = "1 jogador tem a própria bênção"
L["1 profile on this account"] = "1 perfil nesta conta"
L["1 raid"] = "1 raide"
L["1 runs Naowh Forever"] = "1 usa Naowh Forever"
L["1 setting changed from its default"] = "1 configuração alterada do padrão"
L["1 spell"] = "1 feitiço"
L["1 Unspent Talent Point"] = "1 ponto de talento não gasto"
L["1. PICK YOUR BARS"] = "1. ESCOLHA SUAS BARRAS"
L["100%  (default)"] = "100%  (padrão)"
L["100%, native resolution"] = "100%, resolução nativa"
L["12-hour clock"] = "Relógio de 12 horas"
L["16x Anisotropic"] = "Anisotrópico 16x"
L["2. ALSO KEEP"] = "2. MANTER TAMBÉM"
L["24-Hour Clock"] = "Relógio de 24 horas"
L["24-hour clock"] = "Relógio de 24 horas"
L["3. NAME AND SAVE"] = "3. NOMEAR E SALVAR"
L["30, while the game is not in focus"] = "30, enquanto o jogo não está em foco"
L[": copy ID or Wowhead link"] = ": copiar ID ou link do Wowhead"
L[": mail expiring soon on "] = ": correspondência expirando em breve em "
L["; buys at vendors"] = "; compra de mercadores"
L["<AFK>"] = "<LDT>"
L["<DND>"] = "<NP>"
L["[Where?]"] = "[Onde?]"
L["A /thank to everyone around you when the game cannot name the caster."] = "Um /thank para todos ao redor quando o jogo não consegue dizer quem lançou."
L["A [Where?] link after a whisper from someone whose zone is not known. Clicking it runs a /who for them and prints their zone; their next messages are tagged."] = "Um link [Onde?] após um sussurro de alguém cuja zona não é conhecida. Clicar executa um /who e mostra a zona; as próximas mensagens dessa pessoa são marcadas."
L["A banner and a sound when one of them joins your group."] = "Um banner e um som quando um deles entrar no seu grupo."
L["A bar at the threat where you would pull aggro, so the gap to it is easy to read."] = "Uma barra na ameaça em que você puxaria o aggro, para ver fácil a distância até ela."
L["A bar for your target's swings, restarted by each physical hit you take while it is targeting you, and shortened when it parries. It is an estimate: the game does not say who hit you or with what, so other attackers, physical specials and bleed ticks restart it too."] = "Uma barra para os golpes do seu alvo, reiniciada a cada acerto físico que você leva enquanto ele mira em você, e encurtada quando ele apara. É uma estimativa: o jogo não diz quem acertou você nem com o quê, então outros atacantes, especiais físicos e ticks de sangramento também a reiniciam."
L["A bar left out is not touched by an import."] = "Uma barra deixada de fora não é alterada por uma importação."
L["A bar per group member with their level and how far through it they are. Every member running Naowh Forever shares their experience, even with this off; anyone else shows their level. Updates wait until combat ends. Move it in the HUD Editor."] = "Uma barra por membro do grupo com o nível e o progresso nele. Todo membro com Naowh Forever compartilha a experiência, mesmo com isto desligado; os outros mostram o nível. As atualizações esperam o fim do combate. Mova no Editor de HUD."
L["A bar with the name, a turn arrow and the distance, while a waypoint is set."] = "Uma barra com o nome, uma seta de direção e a distância, enquanto houver um ponto de rota."
L["A batch of ten, four done, as it shows while you craft."] = "Um lote de dez, quatro prontos, como aparece enquanto você fabrica."
L["A black outline round the clock."] = "Um contorno preto em volta do relógio."
L["A black outline round the FPS / MS readout and the counts, in place of the soft shadow."] = "Um contorno preto em volta do FPS / MS e das contagens, no lugar da sombra suave."
L["A black outline round the text, in place of the soft shadow."] = "Um contorno preto em volta do texto, no lugar da sombra suave."
L["A button per set: click to equip, Shift-click to save what you wear into it, Ctrl-click to rename it, right-click to change its icon, and + to save a new one. The set you wear is outlined. Move it in the HUD Editor."] = "Um botão por conjunto: clique para equipar, Shift+clique para salvar o que você está usando nele, Ctrl+clique para renomear, clique direito para trocar o ícone e + para salvar um novo. O conjunto em uso fica contornado. Mova no Editor de HUD."
L["A button that flags or unflags you for PvP, showing which you are."] = "Um botão que ativa ou desativa o JxJ, mostrando qual está valendo."
L["A campfire in range and Camp Benefits about to run out."] = "Uma fogueira ao alcance e Benefícios de Acampamento prestes a acabar."
L["A campfire in range and no Camp Benefits."] = "Uma fogueira ao alcance e sem Benefícios de Acampamento."
L["A campfire is in range"] = "Há uma fogueira ao alcance"
L["A card behind the text, a soft dark fade, or nothing at all."] = "Um cartão atrás do texto, um esmaecido escuro suave ou nada."
L["A card over the pin with what it is and how far."] = "Um cartão sobre o marcador com o que é e a que distância."
L["A cast part way through, swept around the ring."] = "Um lançamento pela metade, girando em volta do anel."
L["A cast someone interrupted, held for the fade time."] = "Um lançamento que alguém interrompeu, mantido pelo tempo de esmaecimento."
L["A cast while your interrupt is on cooldown, with the tick where it comes back."] = "Um lançamento enquanto sua interrupção está em recarga, com a marca de quando ela volta."
L["A cast while your interrupt is ready."] = "Um lançamento enquanto sua interrupção está pronta."
L["A cast you cannot interrupt, with its shield."] = "Um lançamento que você não pode interromper, com o escudo."
L["A character shows up here after you log into it with Instance Tracker on. Track Alts shows the others: rested experience and durability, from the last time that character was logged in."] = "Um personagem aparece aqui depois que você entra com ele com o Rastreador de instâncias ligado. Rastrear alts mostra os outros: experiência de descanso e durabilidade, da última vez que o personagem entrou."
L["A choice among its rewards: pick this one."] = "Uma escolha entre as recompensas: escolha esta."
L["A command name can only use letters, numbers and underscores."] = "Um nome de comando só pode usar letras, números e sublinhados."
L["A consumable or personal buff with less time than this left counts as missing."] = "Um consumível ou bônus pessoal com menos tempo restante que isto conta como faltando."
L["A crosshair at the middle of your screen."] = "Uma mira no meio da tela."
L["A cup beside a healer who is drinking."] = "Um copo ao lado de um curador que está bebendo."
L["A custom command can't reload. Type /reload."] = "Um comando personalizado não pode recarregar. Digite /reload."
L["A dark or light fill and edge behind each line, or none."] = "Um preenchimento e borda escuros ou claros atrás de cada linha, ou nada."
L["A dark panel behind the icons."] = "Um painel escuro atrás dos ícones."
L["A different macro already uses that name; rename it before adding the profile macro."] = "Outra macro já usa esse nome; renomeie-a antes de adicionar a macro do perfil."
L["A door on each dungeon and raid entrance on the world map, for the sides the Journal lists. Hover it for the levels, click it for a waypoint."] = "Uma porta em cada entrada de masmorra e raide no mapa-múndi, para os lados que o Diário lista. Passe o mouse para ver os níveis, clique para um ponto de rota."
L["A dot on a slot where a better enchant for your level waits: hover it for the advice, click it to ask in Trade."] = "Um ponto em um espaço onde há um encantamento melhor para seu nível: passe o mouse para a dica, clique para pedir no Comércio."
L["A fading trail behind the cursor."] = "Um rastro que esmaece atrás do cursor."
L["A few quick steps for %s only, its own modules included."] = "Alguns passos rápidos só para %s, incluindo os próprios módulos."
L["A game that opens when a flight starts and closes when you land."] = "Um jogo que abre quando um voo começa e fecha quando você pousa."
L["A game to pass the flight: the Quiz or the Aim Trainer. It closes when you land."] = "Um jogo para passar o voo: o Quiz ou o Treino de mira. Fecha quando você pousa."
L["A gear set called %s already exists."] = "Já existe um conjunto chamado %s."
L["A glow on the moving edge of the fill."] = "Um brilho na borda em movimento do preenchimento."
L["A hidden quest chain across Azeroth: click each thing in the world in turn. It gives a lot of experience, and ends in the Cozy Sleeping Bag; rest in it for a bonus to experience."] = "Uma cadeia de missões escondida por Azeroth: clique em cada coisa no mundo, uma de cada vez. Dá muita experiência e termina no Saco de Dormir Aconchegante; descanse nele para um bônus de experiência."
L["A key that opens Group Inspect."] = "Uma tecla que abre a Inspeção de grupo."
L["A key that shows a boss's loot at your cursor."] = "Uma tecla que mostra o saque de um chefe no seu cursor."
L["A key that uses this item."] = "Uma tecla que usa este item."
L["A later point needs it. "] = "Um ponto posterior depende dele. "
L["A later step."] = "Uma etapa posterior."
L["A line for each quest you turn in, with the experience and money it gave. Reward items show as their own lines."] = "Uma linha para cada missão entregue, com a experiência e o dinheiro que ela deu. Itens de recompensa aparecem em linhas próprias."
L["A line for every reputation gain, from quests and kills alike."] = "Uma linha para cada ganho de reputação, de missões ou de abates."
L["A line for the experience from each kill. Quest experience is on the quest's own line."] = "Uma linha para a experiência de cada abate. A experiência de missão fica na linha da missão."
L["A line from the pin down to a map pin's or corpse's spot."] = "Uma linha do marcador até o local de um marcador do mapa ou do cadáver."
L["A line in chat with the item's link."] = "Uma linha no chat com o link do item."
L["A line in their color on their player tooltip."] = "Uma linha na cor deles na dica do jogador."
L["A line to share them with."] = "Uma linha para compartilhá-los."
L["A line under the ID saying which keys copy it (Ctrl-Shift-C: copy ID or Wowhead link). Off, the shortcut still works; the line is just not shown."] = "Uma linha abaixo do ID dizendo quais teclas o copiam (Ctrl+Shift+C: copiar ID ou link do Wowhead). Desligado, o atalho continua funcionando; só a linha não aparece."
L["A look you do not have yet|r"] = "Um visual que você ainda não tem|r"
L["a macro made on this character"] = "uma macro criada neste personagem"
L["A macro this character does not have yet: the import makes it."] = "Uma macro que este personagem ainda não tem: a importação a cria."
L["A minimap button that opens %s. /nf%s does the same, and the Top Bar can carry it too. Saved for this computer."] = "Um botão no minimapa que abre %s. /nf%s faz o mesmo, e a Barra superior também pode tê-lo. Salvo para este computador."
L["A Naowh weights line, or a WoWSims EP export (in WoWSims: Stat Weights, Copy to Current EP, Export)"] = "Uma linha de pesos do Naowh, ou uma exportação de EP do WoWSims (no WoWSims: Stat Weights, Copy to Current EP, Export)"
L["A Naowh weights line, or a WoWSims EP export."] = "Uma linha de pesos do Naowh, ou uma exportação de EP do WoWSims."
L["A new session, before any experience."] = "Uma nova sessão, antes de qualquer experiência."
L["A parry by your target took 40% off its swing."] = "Uma aparada do seu alvo tirou 40% do golpe dele."
L["A party of five, a card each."] = "Um grupo de cinco, um cartão cada."
L["A player's score on their tooltip. One running Naowh Forever shares theirs; anyone else's is read from their gear when you hover them, within inspect range and out of combat."] = "A pontuação de um jogador na dica dele. Quem usa Naowh Forever compartilha a sua; a dos outros é lida do equipamento quando você passa o mouse, dentro do alcance de inspeção e fora de combate."
L["A profile"] = "Um perfil"
L["A profile macro needs a name (1-16 characters) and body (1-255 characters)."] = "Uma macro de perfil precisa de nome (1-16 caracteres) e corpo (1-255 caracteres)."
L["a quest"] = "uma missão"
L["A quest reward for the other faction; try the Auction House."] = "Uma recompensa de missão da outra facção; tente a Casa de Leilões."
L["A raid for %d players"] = "Uma raide para %d jogadores"
L["A raid, a row each."] = "Uma raide, uma linha cada."
L["A rare someone else is fighting."] = "Um raro que outra pessoa está enfrentando."
L["A rare you have killed before."] = "Um raro que você já matou."
L["A rare you have not killed yet."] = "Um raro que você ainda não matou."
L["A reward from the quest "] = "Uma recompensa da missão "
L["A ring around your cursor so you never lose it in a busy fight, with your global cooldown and casts swept around it."] = "Um anel em volta do cursor para você nunca perdê-lo numa luta agitada, com a recarga global e os lançamentos girando em volta."
L["A round in progress."] = "Uma rodada em andamento."
L["A row of icons for missing food, flask, elixir and scroll buffs, your own class buff, and class buffs missing in your group. Out of combat only: the game keeps your buffs from addons in combat, so the icons keep what they showed. Hover one to pick a carried item to use. Move them in the HUD Editor."] = "Uma fileira de ícones para bônus de comida, frasco, elixir e pergaminho faltando, seu bônus de classe e bônus de classe faltando no grupo. Só fora de combate: em combate o jogo esconde seus bônus dos addons, então os ícones mantêm o que mostravam. Passe o mouse em um para escolher um item carregado para usar. Mova no Editor de HUD."
L["A running gold per hour beside the newest line, counting money and item value since your first loot this session."] = "Um ouro por hora corrente ao lado da linha mais nova, contando dinheiro e valor dos itens desde o primeiro saque desta sessão."
L["A Scan Prices button on the auction house. It reads every listing and keeps the lowest buyout for each item, for this realm and faction. Blizzard allows one full scan every 15 minutes."] = "Um botão Verificar preços na casa de leilões. Ele lê todos os anúncios e guarda o menor preço de arremate de cada item, para este reino e facção. A Blizzard permite uma verificação completa a cada 15 minutos."
L["A scrap icon on the bag slot of each item marked as scrap."] = "Um ícone de sucata no espaço da bolsa de cada item marcado como sucata."
L["A second panel for your focus, to keep Sap or Polymorph's time on one enemy while you fight another."] = "Um segundo painel para o seu foco, para acompanhar o tempo de Aturdir ou Polimorfia em um inimigo enquanto luta com outro."
L["A set that goes on by itself while you ride or rest, and the set you had on goes back afterwards."] = "Um conjunto que é equipado sozinho enquanto você cavalga ou descansa, e o conjunto anterior volta depois."
L["A shooting game for flights: click the other faction's races as fast as you can."] = "Um jogo de tiro para voos: clique nas raças da outra facção o mais rápido que puder."
L["A short flash of text entering and leaving combat. Move it in the HUD Editor."] = "Um texto rápido ao entrar e sair de combate. Mova no Editor de HUD."
L["A small bar with your next trainer visit and your gold, to leave up while you level. Move it by dragging."] = "Uma barrinha com sua próxima visita ao instrutor e seu ouro, para deixar aberta enquanto sobe de nível. Arraste para mover."
L["A small health bar for the other tank in your group, shown while you are tanking: tank role, Bear Form, Defensive Stance or Righteous Fury. The other tank is whoever has the tank role or the raid's Main Tank assignment. Click it to target them. Changes made in combat apply when the fight ends. Move it in the HUD Editor."] = "Uma pequena barra de vida para o outro tanque do grupo, exibida enquanto você tanqueia: função de tanque, Forma de Urso, Postura de Defesa ou Fúria Virtuosa. O outro tanque é quem tem a função de tanque ou a atribuição de Tanque principal na raide. Clique para selecioná-lo. Mudanças em combate valem quando a luta acaba. Mova no Editor de HUD."
L["A soft glow around Naowh's arrow."] = "Um brilho suave em volta da seta do Naowh."
L["A soft glow beside each icon."] = "Um brilho suave ao lado de cada ícone."
L["A soft glow round it in your accent color."] = "Um brilho suave em volta na sua cor de destaque."
L["A soft glow round it in your rank's color."] = "Um brilho suave em volta na cor da sua patente."
L["A soft ring pulses around each target."] = "Um anel suave pulsa em volta de cada alvo."
L["a sound to refresh"] = "um som para renovar"
L["A sound, or the Speech text read aloud, as each cast starts."] = "Um som, ou o texto de Fala lido em voz alta, quando cada lançamento começa."
L["A sound, or the Speech text read aloud. Text to Speech can stutter on some PCs, as the game waits while Windows speaks it; a Sound costs nothing."] = "Um som, ou o texto de Fala lido em voz alta. A conversão de texto em fala pode travar em alguns PCs, pois o jogo espera enquanto o Windows fala; um Som não custa nada."
L["A spell an import could not place because you do not know it yet goes into its saved slot when you learn it, unless you have put something else there."] = "Um feitiço que uma importação não pôde colocar porque você ainda não o conhece vai para o espaço salvo quando você aprendê-lo, a menos que você tenha posto outra coisa lá."
L["A Stack button on the card when part-filled stacks of an item can be combined."] = "Um botão Empilhar no cartão quando pilhas incompletas de um item podem ser combinadas."
L["A star on the world map for every rare you have not killed, where it is most likely to be. Hover one for the rare and its drops, its other spawn spots and, if it patrols, its way; click it for a waypoint, right-click it to keep its spots and way shown."] = "Uma estrela no mapa-múndi para cada raro que você não matou, onde é mais provável que ele esteja. Passe o mouse para ver o raro e o saque, os outros pontos de surgimento e, se ele patrulha, o caminho; clique para um ponto de rota, clique direito para manter os pontos e o caminho visíveis."
L["A string to share it with."] = "Um texto para compartilhá-lo."
L["A supporter"] = "Um apoiador"
L["A team member"] = "Um membro da equipe"
L["A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there."] = "Um texto na barra: clique nele na prévia para trocar. Cada texto aparece em um lugar da barra: escolher um que está em outro lugar o move para cá."
L["A tick on the bar where your interrupt comes off cooldown. Hidden while it is ready."] = "Uma marca na barra onde sua interrupção sai da recarga. Oculta enquanto está pronta."
L["A title bar naming the mob the threat is on."] = "Uma barra de título com o nome do inimigo em que está a ameaça."
L["A trained spell drops into its saved slot."] = "Um feitiço treinado vai para o espaço salvo."
L["a vendor sells the formula"] = "um mercador vende a fórmula"
L["A warning when a rare is near"] = "Um aviso quando um raro estiver perto"
L["A warning when a rare is near you: when its nameplate comes up, you mouse over it or target it. A card with its portrait: right-click it to close it, and its pin sets a waypoint to the rare. Move it in the HUD Editor."] = "Um aviso quando um raro estiver perto de você: quando a placa de identificação dele aparece, você passa o mouse ou o seleciona. Um cartão com o retrato: clique direito para fechar, e o marcador dele cria um ponto de rota até o raro. Mova no Editor de HUD."
L["A warning while a hunter or warlock has no pet out. A warlock who sacrificed their demon is left alone. Move it in the HUD Editor."] = "Um aviso enquanto um caçador ou bruxo estiver sem ajudante. Um bruxo que sacrificou o demônio é deixado em paz. Mova no Editor de HUD."
L["A word of your own on the icon."] = "Uma palavra sua no ícone."
L["A world drop from %d kinds of mob"] = "Um saque do mundo de %d |4tipo de inimigo:tipos de inimigo;"
L["A WoW quiz for campfires and flights, or any time with /naowh quiz."] = "Um quiz de WoW para fogueiras e voos, ou a qualquer hora com /naowh quiz."
L["A yellow ! on the world map at every quest giver with a quest you can pick up that still gives experience. Hover it for the quests; click it for a waypoint."] = "Um ! amarelo no mapa-múndi em cada PNJ de missão com uma missão que você pode pegar e que ainda dá experiência. Passe o mouse para ver as missões; clique para um ponto de rota."
L["A zone older than this is no longer shown, since the player has likely moved on."] = "Uma zona mais antiga que isto não é mais exibida, pois o jogador provavelmente já seguiu em frente."
L["Abandon %s?"] = "Abandonar %s?"
L["Abilities"] = "Habilidades"
L["about "] = "cerca de "
L["about %d:%02d"] = "cerca de %d:%02d"
L["About %s at your last scan%s%s"] = "Cerca de %s na última verificação%s%s"
L["About %s spent"] = "Cerca de %s gastos"
L["About a minute."] = "Cerca de um minuto."
L["Above"] = "Acima"
L["Acc."] = "Prec."
L["Accent: missing the class blessing. Lighter: running out. Deeper: only players with their own."] = "Destaque: falta a bênção da classe. Mais claro: acabando. Mais escuro: só jogadores com a própria."
L["Accept Quests"] = "Aceitar missões"
L["Accept Shared Dungeon Quests"] = "Aceitar missões de masmorra compartilhadas"
L["Accepts a quest as soon as its text opens. Use the Modifier to read it first."] = "Aceita uma missão assim que o texto abre. Use o Modificador para ler antes."
L["Accepts dungeon quests your group shares with you straight away."] = "Aceita na hora as missões de masmorra que seu grupo compartilha com você."
L["Accepts shared quests"] = "Aceita missões compartilhadas"
L["Accepts the popup on screen: a summons, a resurrection, a group invite."] = "Aceita o aviso na tela: uma invocação, uma ressurreição, um convite de grupo."
L["Accepts, hands in and shares quests for you, and remembers the reward you saved for a quest. The Modifier skips them or triggers them, as Modifier Does says."] = "Aceita, entrega e compartilha missões para você, e lembra a recompensa salva para uma missão. O Modificador as pula ou as dispara, conforme O que o Modificador faz."
L["Account"] = "Conta"
L["Account "] = "Conta "
L["Account macros"] = "Macros da conta"
L["Account this hour: %d of %d"] = "Conta nesta hora: %d de %d"
L["Accuracy"] = "Precisão"
L["Action Bars is switched off."] = "Barras de ação está desligado."
L["Action Bars' own window, with your class's saved sets."] = "A janela própria de Barras de ação, com os conjuntos salvos da sua classe."
L["Active"] = "Ativo"
L["Activity Bar"] = "Barra de atividade"
L["Activity Bar Color"] = "Cor da barra de atividade"
L["Activity Bar Height"] = "Altura da barra de atividade"
L["Add %d item to your scrap list: %s%s?"] = "Adicionar %d item à sua lista de sucata: %s%s?"
L["Add %d items to your scrap list: %s%s?"] = "Adicionar %d itens à sua lista de sucata: %s%s?"
L["Add %d macro as character macros?%s"] = "Adicionar %d macro como macro de personagem?%s"
L["Add %d macros as character macros?%s"] = "Adicionar %d macros como macros de personagem?%s"
L["Add %s"] = "Adicionar %s"
L["Add %s (%d items) as a new BiS list?"] = "Adicionar %s (%d itens) como nova lista BiS?"
L["Add %s to the Consumable Bar?"] = "Adicionar %s à Barra de consumíveis?"
L["Add a backup pick"] = "Adicionar escolha reserva"
L["Add a Button"] = "Adicionar botão"
L["Add a stat"] = "Adicionar atributo"
L["Add an item ID, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "Adicione um ID de item ou importe uma lista. Comida conta qualquer bônus Bem Alimentado, e outros itens o próprio bônus; adicione IDs de feitiço de bônus só para um item que dá outro. Nada é adicionado automaticamente. Passe o mouse em um lembrete para escolher um item configurado das bolsas. Lembretes pausam em combate; menus de itens funcionam fora de combate. Quando e onde aparecem fica em AuraBuffs > Configurações."
L["Add consumables, put them in order, and set each one up."] = "Adicione consumíveis, ordene e configure cada um."
L["Add Items"] = "Adicionar itens"
L["Add Latency"] = "Somar latência"
L["Add macros someone shared with you."] = "Adicione macros que alguém compartilhou com você."
L["Add or remove your commands, turn each one on or off, or restore the defaults."] = "Adicione ou remova seus comandos, ligue ou desligue cada um, ou restaure os padrões."
L["Add Slash Command"] = "Adicionar comando de barra"
L["Add the %s build %s (%d points)?"] = "Adicionar a build de %s %s (%d pontos)?"
L["Add the consumables to watch in the AuraBuffs window."] = "Adicione os consumíveis a monitorar na janela do AuraBuffs."
