L["Add your consumables, put them in order, set each one up."] = "Adicione seus consumíveis, ordene e configure cada um."
L["Add your own lines to the bag macros. They are kept after the item, whatever is in your bags."] = "Adicione suas próprias linhas às macros de bolsa. Elas ficam depois do item, seja o que for que estiver nas bolsas."
L["Added %d consumable to the Consumable Bar."] = "%d consumível adicionado à Barra de consumíveis."
