L["Addon Memory"] = "Memória dos addons"
L["Adds \"- [1] + Add to List\" under a recipe's reagents: the materials Buy on AH would buy for that many crafts go on a shopping list, from anywhere. At the auction house the list shows beside it: Check Prices looks each one up and warns in red when one is well above your last scan, then Buy All goes through the list one material at a time, each bought only when you confirm its final price. A material you can make for less from its parts, such as a bar from ore, has its parts bought instead."] = "Adiciona \"- [1] + Adicionar à lista\" abaixo dos reagentes de uma receita: os materiais que Comprar na CL compraria para essa quantidade de criações vão para uma lista de compras, de qualquer lugar. Na casa de leilões a lista aparece ao lado: Verificar preços consulta cada um e avisa em vermelho quando algum está bem acima da sua última verificação, e Comprar tudo percorre a lista um material por vez, comprando cada um só quando você confirma o preço final. Um material que você pode fabricar mais barato a partir das partes, como uma barra a partir de minério, tem as partes compradas no lugar."
L["Adds a Bags column to the chosen recipe's reagents, showing how many of each you carry."] = "Adiciona uma coluna Bolsas aos reagentes da receita escolhida, mostrando quantos de cada você carrega."
L["Adds a Bank column to the chosen recipe's reagents, showing how many of each are in your bank."] = "Adiciona uma coluna Banco aos reagentes da receita escolhida, mostrando quantos de cada estão no seu banco."
L["Adds a button to the popup that swaps every lower rank on your bars for the highest rank you know. Keyboard and controller bars land in the same slot. Right-click a spell in the popup to keep its lower ranks, for downranking. Rank swaps only happen out of combat."] = "Adiciona ao aviso um botão que troca cada patente menor nas suas barras pela maior que você conhece. Barras de teclado e de controle ficam no mesmo espaço. Clique direito em um feitiço no aviso para manter as patentes menores, para usar patente menor. As trocas só acontecem fora de combate."
L["Adds a Land button to come down at the next stop on the way."] = "Adiciona um botão Pousar para descer na próxima parada do caminho."
L["Adds a line that flags any slot whose enchant is missing or differs from the ones you captured with Capture Current Enchants. Hover it for the details."] = "Adiciona uma linha que aponta qualquer espaço cujo encantamento falta ou difere dos que você capturou com Capturar encantamentos atuais. Passe o mouse para ver os detalhes."
L["Adds a mana spell's healing or damage per mana and per second to its tooltip."] = "Adiciona à dica de um feitiço de mana a cura ou o dano por mana e por segundo."
L["Adds a second, orange number next to each recipe: how many you could make after buying the reagents vendors sell, such as Weak Flux or Coarse Thread. The recipe's reagents then say how many of each to buy."] = "Adiciona um segundo número, laranja, ao lado de cada receita: quantos você poderia fazer depois de comprar os reagentes vendidos por mercadores, como Fundente Fraco ou Linha Grossa. Os reagentes da receita então dizem quanto comprar de cada um."
L["Adds how long the visit lasted."] = "Adiciona quanto tempo a visita durou."
L["Adds target and focus switching to the meter's title bar."] = "Adiciona a troca entre alvo e foco na barra de título do medidor."
L["Adds the average experience here."] = "Adiciona a experiência média aqui."
L["Adds the coins looted."] = "Adiciona as moedas saqueadas."
L["Adds the consumables in your bags that are not on the bar yet."] = "Adiciona os consumíveis das bolsas que ainda não estão na barra."
L["Adds the deaths."] = "Adiciona as mortes."
L["Adds the experience gained."] = "Adiciona a experiência ganha."
L["Adds the materials for one more craft."] = "Adiciona os materiais para mais uma criação."
L["Adds the Naowh themes to RestedXP's theme list."] = "Adiciona os temas do Naowh à lista de temas do RestedXP."
L["Adds the reputation gained."] = "Adiciona a reputação ganha."
L["Adds the visits at this level."] = "Adiciona as visitas neste nível."
