L["Alt-click a reward you can choose, in the quest log or at the quest giver, to save it for that quest in this profile; Alt-click it again to clear it. It is selected when you hand the quest in, and Hand In Quests takes it for you."] = "Alt+clique em uma recompensa que você pode escolher, no registro de missões ou no PNJ de missão, para salvá-la para essa missão neste perfil; Alt+clique de novo para limpar. Ela é selecionada quando você entrega a missão, e Entregar missões a pega para você."
L["Alt-click an item in your bags to mark it as scrap, and sell it at the next vendor."] = "Alt+clique em um item nas bolsas para marcá-lo como sucata e vendê-lo no próximo mercador."
