L["An Alts button beside the mailbox's Send tab lists your characters on this realm and faction with their level and gold. Pick one to fill the To box."] = "Um botão Alts ao lado da aba Enviar do correio lista seus personagens neste reino e facção com nível e ouro. Escolha um para preencher o campo Para."
L["An Attach button beside the mailbox's Send tab: attach every trade good, one type of trade good, or your unbound gear in one click."] = "Um botão Anexar ao lado da aba Enviar do correio: anexe todas as mercadorias, um tipo de mercadoria ou seu equipamento não vinculado em um clique."
L["An ID the game keeps hidden: Hide Line leaves it off the tooltip, Show Hidden shows the line with Hidden in place of the number."] = "Um ID que o jogo mantém oculto: Ocultar linha tira da dica, Mostrar oculto mostra a linha com Oculto no lugar do número."
L["An item worth more at the auction house than at a vendor is valued at its auction price, from your last Scan Prices or TradeSkillMaster."] = "Um item que vale mais na casa de leilões que no mercador é avaliado pelo preço do leilão, da sua última Verificação de preços ou do TradeSkillMaster."
