L["At a profession trainer who teaches any of your favourite recipes that you can learn now (star one before its name, or right-click it in the list), a window beside the trainer's lists them with their cost: Learn one, or Learn All."] = "Em um instrutor de profissão que ensina alguma das suas receitas favoritas que você já pode aprender (marque com a estrela antes do nome, ou clique direito na lista), uma janela ao lado do instrutor lista essas receitas com o custo: Aprender uma ou Aprender tudo."
L["At a vendor who sells them, tops your class reagents and ammo up to what you carry, and prints what it spent. Off by default: it spends gold for you."] = "Em um mercador que os vende, completa seus reagentes de classe e munição até o que você carrega, e mostra quanto gastou. Desligado por padrão: gasta ouro por você."
