L["At the auction house, a window beside it lists the patterns, plans and manuals of your favourite recipes that you have not learned or bought, with what they cost now. Buy finds the cheapest and asks before Accept buys it."] = "Na casa de leilões, uma janela ao lado lista os moldes, planos e manuais das suas receitas favoritas que você não aprendeu nem comprou, com o preço atual. Comprar encontra o mais barato e pergunta antes que Aceitar compre."
