L["Drag the right edge for width. Wheel: text size (Shift: height). Click a bonus or the time to show or hide it. Right-click for more."] = "Arraste a borda direita para a largura. Roda: tamanho do texto (Shift: altura). Clique em um bônus ou no tempo para mostrar ou ocultar. Clique direito para mais."
