L["Each class's name or icon, under its button or beside it when the bar is vertical."] = "O nome ou ícone de cada classe, abaixo do botão ou ao lado quando a barra é vertical."
L["Each dungeon or raid visit while Instance Tracker is on: how long you were inside, the coins you looted and the experience you gained. Reputation gained is listed under the visit. Coming back to the same group within the hour, before you reset it, continues that visit, and the time outside is not counted. Other characters stay saved, and show here when Track Alts is on. Repairs and vendor sales are not counted. Older visits drop off the end of the list."] = "Cada visita a masmorra ou raide com o Rastreador de instâncias ligado: quanto tempo você ficou lá dentro, as moedas saqueadas e a experiência ganha. A reputação ganha é listada abaixo da visita. Voltar ao mesmo grupo dentro da hora, antes de reiniciá-la, continua aquela visita, e o tempo fora não conta. Outros personagens continuam salvos e aparecem aqui quando Rastrear alts está ligado. Reparos e vendas a mercadores não contam. Visitas mais antigas saem do fim da lista."
L["Each line fades out after %ss."] = "Cada linha esmaece após %ss."
L["Each one is an account macro. Put it on a bar once and it keeps itself current: loot a better potion, conjure fresh food or pick up bandages and the macro is rewritten to use the best you carry.\n\nThe game does not let macros change mid-fight, so a change during combat waits until it ends."] = "Cada uma é uma macro da conta. Coloque-a numa barra uma vez e ela se mantém atualizada: saqueie uma poção melhor, conjure comida nova ou pegue ataduras e a macro é reescrita para usar o melhor que você carrega.\n\nO jogo não deixa macros mudarem no meio da luta, então uma mudança durante o combate espera até ele acabar."
L["Each point of the trail in a color of its own."] = "Cada ponto do rastro em uma cor própria."
L["Each slot's item level, in its icon's corner."] = "O nível de item de cada espaço, no canto do ícone."
