L["For paladins, a button per class in your group. Left-click blesses the next member of that class who needs it, missing first, skipping anyone dead or out of range. Right-click a class to choose its blessing or open its player list. Move it in the HUD Editor. The preview edits it: right-click a class for its blessing, click the aura to choose it, wheel for size and Shift-wheel for spacing, drag the gap after the aura, x hides a button and + brings it back."] = "Para paladinos, um botão por classe no seu grupo. Clique esquerdo abençoa o próximo membro daquela classe que precisa, os que estão sem primeiro, pulando mortos ou fora de alcance. Clique direito em uma classe para escolher a bênção ou abrir a lista de jogadores. Mova no Editor de HUD. A prévia o edita: clique direito em uma classe para a bênção, clique na aura para escolhê-la, roda para o tamanho e Shift+roda para o espaçamento, arraste o espaço após a aura, x oculta um botão e + o traz de volta."
L["For Skyborne characters: ley lines (Alliance, for Read Ley Line) or Elemental Convergences (Horde, for Skysight) pinned on the world map. The game does not mark them: the addon knows the ones players have found, and saves each new one you cast your racial on. Other races see no pins."] = "Para personagens Skyborne: meridianos (Aliança, para Ler Meridianos) ou Convergências Elementais (Horda, para Visão do Céu) marcados no mapa-múndi. O jogo não os marca: o addon conhece os que os jogadores encontraram e salva cada novo em que você lançar sua habilidade racial. Outras raças não veem marcadores."
L["For your class: imports this set once on a new character, at level 1 with no experience yet."] = "Para sua classe: importa este conjunto uma vez em um personagem novo, no nível 1 e ainda sem experiência."
L["For your level"] = "Para seu nível"
L["Forget %s on %s? It comes back the next time you log in on it with a Mail & Alts option on."] = "Esquecer %s em %s? Ele volta na próxima vez que você entrar com ele com uma opção de Correio e alts ligada."
