L["How close a book has to be before it pings."] = "A que distância um livro precisa estar para dar o sinal."
L["How early you can press your next spell before the current one finishes, in milliseconds. 100 to 400 suits most: lower is more responsive, higher is more forgiving of latency. Melee around your ping + 100, ranged around your ping + 150."] = "Quanto antes você pode pressionar o próximo feitiço antes que o atual termine, em milissegundos. 100 a 400 serve para a maioria: menor responde mais rápido, maior tolera mais latência. Corpo a corpo por volta do seu ping + 100, à distância por volta do seu ping + 150."
L["How far along an icon starts to fade, from 0% (at once) to 95% (at the very end)."] = "Em que ponto um ícone começa a esmaecer, de 0% (na hora) a 95% (bem no fim)."
