L["Invites the crafter to your group, with a whisper saying it is for crafts from their profession. Once they are in your party, Ask sends the order in party chat instead of whispering it. Greyed out once they are in your group, or while you are in a group and not its leader or an assistant."] = "Convida o artesão para o seu grupo, com um sussurro dizendo que é para criações da profissão dele. Quando ele estiver no grupo, Pedir envia o pedido no chat do grupo em vez de sussurrar. Esmaecido quando ele já está no grupo, ou enquanto você está em um grupo e não é líder nem assistente."
L["Invites your target. Works in combat."] = "Convida seu alvo. Funciona em combate."
