L["Makes the set's macros that this character does not have. A macro you already have, by name and text or by text alone, is used as it is: never copied twice or changed."] = "Cria as macros do conjunto que este personagem não tem. Uma macro que você já tem, por nome e texto ou só pelo texto, é usada como está: nunca copiada duas vezes nem alterada."
L["Makes the windowed world map bigger or smaller and lets you move it: drag the grip in its bottom right corner or set the size here, and drag its title bar to move it (right-click the title bar puts it back). The full screen map keeps its size and place."] = "Aumenta ou diminui o mapa-múndi em janela e deixa você movê-lo: arraste a alça no canto inferior direito ou defina o tamanho aqui, e arraste a barra de título para mover (clique direito na barra de título o devolve). O mapa em tela cheia mantém tamanho e lugar."
L["Makes this recipe a favourite, or no longer one. Favourites get a star in the list, and the Filter menu's Favorites shows only them. Right-click a recipe in the list does the same."] = "Torna esta receita favorita, ou não mais. Favoritas ganham uma estrela na lista, e Favoritos no menu Filtro mostra só elas. Clique direito em uma receita na lista faz o mesmo."
L["Makes this recipe a favourite, or no longer one. With Train Favorites on, a trainer who teaches it offers it when you visit; with Search Favorites AH on, its pattern, plans or manual is listed at the auction house to search for."] = "Torna esta receita favorita, ou não mais. Com Treinar favoritas ligado, um instrutor que a ensina a oferece quando você visita; com Buscar favoritas na CL ligado, o molde, plano ou manual dela é listado na casa de leilões para buscar."
