L["Onboarding"] = "Introdução"
L["Once Per Player Every"] = "Uma vez por jogador a cada"
L["Once you have scanned the auction house (Scan Prices), the chosen recipe shows what its reagents cost to buy and what the item sells for, and the profit after the 5% auction house cut. Each reagent is priced at its cheapest: a vendor's price once you have seen a vendor sell it, else the lowest buyout at your last scan. Uncheck a reagent you already have to leave it out of the cost, for every recipe that uses it. Hover the lines for the breakdown."] = "Depois de verificar a casa de leilões (Verificar preços), a receita escolhida mostra quanto custa comprar os reagentes e por quanto o item vende, e o lucro após a taxa de 5% da casa de leilões. Cada reagente é avaliado pelo mais barato: o preço do mercador depois que você viu um mercador vendê-lo, senão o menor arremate da última verificação. Desmarque um reagente que você já tem para tirá-lo do custo, em todas as receitas que o usam. Passe o mouse nas linhas para o detalhamento."
L["One addon"] = "Um addon"
L["One bar per weapon, timed by the game's own swing event, so parry haste, swing resets and haste are always right. Move them in the HUD Editor."] = "Uma barra por arma, cronometrada pelo próprio evento de golpe do jogo, então aceleração por aparar, reinícios de golpe e aceleração estão sempre certos. Mova no Editor de HUD."
L["One Fewer"] = "Um a menos"
L["One item per click: the game needs a click for every disenchant."] = "Um item por clique: o jogo exige um clique para cada desencantamento."
L["One More"] = "Um a mais"
L["One number for a character's gear, on the item level scale: 26.4 means gear worth a set of level 26 epics. Your own is always on the BiS List's paperdoll."] = "Um número para o equipamento de um personagem, na escala de nível de item: 26.4 significa equipamento que vale um conjunto de épicos de nível 26. O seu fica sempre no boneco da Lista BiS."
L["One whisper per line, picked at random; {buff} and {name} are filled in."] = "Um sussurro por linha, escolhido ao acaso; {buff} e {name} são preenchidos."
