L["opens "] = "abre "
L["Opens another player's profession link in this window, to order crafts from them. Choose a recipe, set how many crafts, tick the materials you bring (or type how many), and Add to Order. The order on the right has a suggested tip per craft that you can change; Ask sends the crafter one message per craft with the amount, your materials and the tip: in party chat when they are in your party, else as a whisper. Prices and the tip need an auction house scan."] = "Abre o link de profissão de outro jogador nesta janela, para pedir criações a ele. Escolha uma receita, defina quantas criações, marque os materiais que você leva (ou digite quantos) e Adicionar ao pedido. O pedido à direita tem uma gorjeta sugerida por criação que você pode mudar; Pedir envia ao artesão uma mensagem por criação com a quantidade, seus materiais e a gorjeta: no chat do grupo quando ele está no seu grupo, senão por sussurro. Preços e gorjeta precisam de uma verificação da casa de leilões."
L["Opens its settings and leaves the HUD Editor."] = "Abre as configurações dele e sai do Editor de HUD."
L["Opens the Aim Trainer now, out of combat."] = "Abre o Treino de mira agora, fora de combate."
L["Opens the AuraBuffs window, where you add each item by its item ID and buff spell ID."] = "Abre a janela do AuraBuffs, onde você adiciona cada item pelo ID do item e ID do feitiço de bônus."
L["Opens the Consumable Bar's settings."] = "Abre as configurações da Barra de consumíveis."
L["Opens the copy card on a sample spell. Select the ID or link, then Ctrl+C."] = "Abre o cartão de cópia em um feitiço de exemplo. Selecione o ID ou link e use Ctrl+C."
L["Opens the Dungeon Journal's Quest Tracker settings."] = "Abre as configurações do Rastreador de missões do Diário de Masmorras."
L["Opens the HUD Editor: click another Naowh Forever element for the bar to move with."] = "Abre o Editor de HUD: clique em outro elemento do Naowh Forever para a barra se mover junto."
L["Opens the Library Books tracker's settings."] = "Abre as configurações do rastreador de Livros da biblioteca."
L["Opens the planner on its Builds tab."] = "Abre o planejador na aba Builds."
L["Opens the quest tracker out in the world, on the dungeon your quests are for."] = "Abre o rastreador de missões pelo mundo, na masmorra das suas missões."
L["Opens the quest tracker when you enter a dungeon with quests for you."] = "Abre o rastreador de missões quando você entra em uma masmorra com missões para você."
L["Opens the quiz now, or closes it."] = "Abre o quiz agora, ou o fecha."
L["Opens the Run Timer settings."] = "Abre as configurações do Timer de corrida."
L["Opens the Sleeping Bag tracker's settings."] = "Abre as configurações do rastreador do Saco de dormir."
L["Opens the Stat Weights window: each stat's worth to your spec, and your best upgrades by them."] = "Abre a janela Pesos de atributos: quanto cada atributo vale para sua especialização, e suas melhores melhorias por eles."
L["Opens the window now, out of combat."] = "Abre a janela agora, fora de combate."
