L["Plays once each time your health drops below the threshold. If the game hides your health from addons mid-fight, it only plays out of combat."] = "Toca uma vez cada vez que sua vida cai abaixo do limite. Se o jogo esconder sua vida dos addons no meio da luta, só toca fora de combate."
