L["Plays the map ping and names the book in chat when you come within range of one you still need. Once per book, until you walk away and come back."] = "Toca o ping do mapa e cita o livro no chat quando você chega ao alcance de um que ainda precisa. Uma vez por livro, até você se afastar e voltar."
