L["Put back every setting this page has changed?"] = "Restaurar todas as configurações que esta página alterou?"
L["put down what you are holding first."] = "solte primeiro o que você está segurando."
L["Put every %s weight back to the defaults?"] = "Voltar todos os pesos de %s ao padrão?"
L["Put every setting back to how it was before the onboarding?"] = "Voltar todas as configurações para como estavam antes da introdução?"
L["Put every setting in this profile back to its default."] = "Volta todas as configurações deste perfil ao padrão."
L["Put on in cities and inns, and taken off again when you leave."] = "Equipado em cidades e estalagens, e tirado de novo quando você sai."
