L["Put the XP Bar colors back to their defaults?"] = "Voltar as cores da Barra de XP ao padrão?"
L["Put the XP Bar's size and texts back to their defaults?"] = "Voltar o tamanho e os textos da Barra de XP ao padrão?"
L["Put this bar back in"] = "Incluir esta barra de novo"
L["Puts a raid marker on your focus. Pressing the macro again on the same focus clears the marker."] = "Coloca um marcador de raide no seu foco. Pressionar a macro de novo no mesmo foco limpa o marcador."
L["Puts back every setting this page has changed, to the value you had before."] = "Restaura todas as configurações que esta página alterou, ao valor que você tinha antes."
L["Puts back everything changed since the HUD Editor opened."] = "Desfaz tudo o que mudou desde que o Editor de HUD abriu."
L["Puts back the last change. Ctrl + Z."] = "Desfaz a última alteração. Ctrl + Z."
L["Puts both back where the game shows them."] = "Devolve os dois para onde o jogo os mostra."
L["Puts every weight of this spec back to the defaults. Asks first."] = "Volta todos os pesos desta especialização ao padrão. Pergunta antes."
L["Puts food, drink and potions 10 or more levels below you, marked with a clock, first."] = "Coloca primeiro comida, bebida e poções 10 ou mais níveis abaixo de você, marcadas com um relógio."
L["Puts the bar back on the screen."] = "Devolve a barra à tela."
L["Puts the bar's buttons back as they came: the Dungeon Journal and Discovery on the left, the BiS List and Training Planner on the right."] = "Devolve os botões da barra como vieram: o Diário de Masmorras e Descobertas à esquerda, a Lista BiS e o Planejador de treinamento à direita."
L["Puts the card back above the middle of the screen, where it starts."] = "Devolve o cartão para cima do meio da tela, onde ele começa."
L["Puts the cheapest item at the far end of the row instead of next to its anchor."] = "Coloca o item mais barato na outra ponta da fileira em vez de junto à âncora."
L["Puts the cheapest item on your cursor, to drop or sell."] = "Coloca o item mais barato no seu cursor, para jogar fora ou vender."
L["Puts the count just past the icon's edge."] = "Coloca a contagem logo além da borda do ícone."
L["Puts the key just past the icon's edge."] = "Coloca a tecla logo além da borda do ícone."
L["Puts the materials for that many crafts on your shopping list: every checked reagent that vendors do not sell, whatever is in your bags. Uncheck a reagent to leave it out. At the auction house the list shows beside it, to check the prices and buy it all."] = "Coloca os materiais para essa quantidade de criações na sua lista de compras: cada reagente marcado que mercadores não vendem, seja o que for que estiver nas bolsas. Desmarque um reagente para deixá-lo de fora. Na casa de leilões a lista aparece ao lado, para verificar os preços e comprar tudo."
L["Puts the popup back where it first showed."] = "Devolve o aviso para onde ele apareceu primeiro."
