L["Shows a dungeon's bosses and loot beside the world map while you are inside."] = "Mostra os chefes e o saque de uma masmorra ao lado do mapa-múndi enquanto você está dentro."
L["Shows a healing item's icon the moment your health drops below the threshold, in combat too: the game shows and hides it itself. Move it in the HUD Editor."] = "Mostra o ícone de um item de cura no momento em que sua vida cai abaixo do limite, inclusive em combate: o próprio jogo mostra e oculta. Mova no Editor de HUD."
L["Shows a sample spell's tooltip with the line as your settings draw it."] = "Mostra a dica de um feitiço de exemplo com a linha como suas configurações a desenham."
L["Shows a zone's level range when you hover it on the world map."] = "Mostra a faixa de níveis de uma zona quando você passa o mouse nela no mapa-múndi."
L["Shows an icon on screen while you know Find Herbs, Find Minerals or Find Fish but are tracking none of them. Click it to start tracking: left-click for the first, right-click for the second, middle-click for the third. Hover it to see which is which. Hidden in combat. Move it in the HUD Editor."] = "Mostra um ícone na tela enquanto você conhece Encontrar Ervas, Encontrar Minerais ou Localizar Peixes mas não está rastreando nenhum. Clique para começar a rastrear: clique esquerdo para o primeiro, direito para o segundo, do meio para o terceiro. Passe o mouse para ver qual é qual. Oculto em combate. Mova no Editor de HUD."
L["Shows each Sleeping Bag step, with how to reach the next one and a waypoint."] = "Mostra cada etapa do Saco de dormir, com como chegar à próxima e um ponto de rota."
L["Shows every bonus again; click one on the preview to hide it."] = "Mostra todos os bônus de novo; clique em um na prévia para ocultá-lo."
L["Shows how many of each you carry."] = "Mostra quantos de cada você carrega."
L["Shows if you're ahead of or behind your other characters, and colors past levels by it."] = "Mostra se você está à frente ou atrás dos seus outros personagens, e colore os níveis passados por isso."
L["Shows it again a little before its effect runs out."] = "Mostra de novo um pouco antes de o efeito acabar."
L["Shows only part of the raid."] = "Mostra só parte da raide."
L["Shows or hides the list of every element."] = "Mostra ou oculta a lista de todos os elementos."
L["Shows the factions earned where you are beside the world map."] = "Mostra ao lado do mapa-múndi as facções que dão reputação onde você está."
L["Shows the key that uses each button."] = "Mostra a tecla que usa cada botão."
L["Shows the meter with sample bars where it sits on your screen, for ten seconds. Out of combat only."] = "Mostra o medidor com barras de exemplo onde ele fica na tela, por dez segundos. Só fora de combate."
L["Shows the other tank's debuffs beside their health bar, in combat too: tank-buster stacks, boss debuffs and anything you can dispel."] = "Mostra as penalidades do outro tanque ao lado da barra de vida dele, inclusive em combate: acúmulos de destruidor de tanque, penalidades de chefe e tudo o que você pode dissipar."
L["Shows the parts of the world map you have not explored yet, darkened."] = "Mostra escurecidas as partes do mapa-múndi que você ainda não explorou."
L["Shows the row only once your bags are this full. 0 shows it all the time."] = "Mostra a fileira só quando suas bolsas estão cheias assim. 0 mostra o tempo todo."
L["Shows the Sleeping Bag steps still to do on your map; click one for a waypoint."] = "Mostra no mapa as etapas do Saco de dormir que faltam; clique em uma para um ponto de rota."
L["Shows the warning with its sound, about your target if you can attack it."] = "Mostra o aviso com o som, sobre seu alvo se você puder atacá-lo."
L["Shows this bonus on the bar: %s."] = "Mostra este bônus na barra: %s."
L["Shows this recipe's reagents in your objective tracker, with how many you have of each."] = "Mostra os reagentes desta receita no rastreador de objetivos, com quantos você tem de cada."
L["Shows this visit's time, coins, and experience."] = "Mostra o tempo, as moedas e a experiência desta visita."
L["Shows up once you take the talent"] = "Aparece quando você pegar o talento"
L["Shows who Naowh, the developers, the moderators and our Legendary and Epic patrons are: a badge by their name in chat, a line on their tooltip and, if you want it, a banner when one of them joins your group."] = "Mostra quem são Naowh, os desenvolvedores, os moderadores e nossos patronos Lendários e Épicos: um emblema junto ao nome no chat, uma linha na dica e, se você quiser, um banner quando um deles entra no seu grupo."
L["Shows your BiS stars to players who inspect you with Naowh Forever."] = "Mostra suas estrelas BiS para jogadores que inspecionam você com Naowh Forever."
L["Shows your note and tag on a player's tooltip."] = "Mostra sua nota e etiqueta na dica de um jogador."
L["Shows your other characters' visits."] = "Mostra as visitas dos seus outros personagens."
