L["The AuraBuffs window: the consumables to watch."] = "A janela do AuraBuffs: os consumíveis a monitorar."
L["The bar and the FPS / MS readout fade to Faded Opacity until you hover them. Their buttons still click while faded."] = "A barra e o FPS / MS esmaecem até a Opacidade esmaecida até você passar o mouse. Os botões ainda funcionam esmaecidos."
L["The bar as it shows outside a fight."] = "A barra como aparece fora de uma luta."
L["The bar as it sits on your screen."] = "A barra como fica na sua tela."
L["The best scores of the players you have met, in this mode."] = "As melhores pontuações dos jogadores que você encontrou, neste modo."
L["The BiS List's own window, and its Stat Weights window."] = "A janela própria da Lista BiS, e a janela de Pesos de atributos dela."
L["The BiS rankings behind the BiS List."] = "As classificações BiS por trás da Lista BiS."
L["The book count is what players report; not confirmed yet."] = "A contagem de livros é o que os jogadores informam; ainda não confirmada."
L["The boss or place it comes from."] = "O chefe ou lugar de onde vem."
L["The buffs show while you hover the icon."] = "Os bônus aparecem enquanto você passa o mouse no ícone."
L["The build's next talent cannot be taken now: your talents are not the build's."] = "O próximo talento da build não pode ser pego agora: seus talentos não são os da build."
L["The calendar cannot be opened from the Top Bar with a gamepad."] = "O calendário não pode ser aberto pela Barra superior com um controle."
L["The card at the end of a round."] = "O cartão no fim de uma rodada."
L["The cheapest items in your bags as a row of icons, cheapest first. Ctrl-click an icon to delete it, or click it to sell it while a vendor is open. Middle-click to ignore an item. Move it in the HUD Editor."] = "Os itens mais baratos nas suas bolsas como uma fileira de ícones, o mais barato primeiro. Ctrl+clique em um ícone para excluí-lo, ou clique para vendê-lo com um mercador aberto. Clique do meio para ignorar um item. Mova no Editor de HUD."
L["The class's name, or its class icon, which fits however small the buttons are."] = "O nome da classe, ou o ícone dela, que cabe por menores que sejam os botões."
L["The color of the line on the tooltip."] = "A cor da linha na dica."
L["The Consumable Bar will ask about those items again."] = "A Barra de consumíveis vai perguntar sobre esses itens de novo."
L["The consumables your reminders watch"] = "Os consumíveis que seus lembretes monitoram"
L["The consumables your reminders watch."] = "Os consumíveis que seus lembretes monitoram."
L["The Cozy Sleeping Bag's hidden quest chain, step by step."] = "A cadeia de missões escondida do Saco de Dormir Aconchegante, passo a passo."
L["The crowd control on your target; pick which in the Crowd Control card below."] = "O controle de grupo no seu alvo; escolha quais no cartão Controle de grupo abaixo."
L["The Ctrl-click line, and Click to sell while a vendor is open."] = "A linha do Ctrl+clique, e Clique para vender com um mercador aberto."
L["The cursor left still."] = "O cursor ficou parado."
L["The debuffs on your target you pick in the Debuffs card below, like Mortal Strike."] = "As penalidades no seu alvo que você escolhe no cartão Penalidades abaixo, como Golpe Mortal."
L["The default is %s."] = "O padrão é %s."
L["The default is %s. Click to put it back."] = "O padrão é %s. Clique para restaurá-lo."
L["The Disenchant window cannot open in combat."] = "A janela de desencantamento não pode abrir em combate."
L["The Dungeon Quest Tracker's window."] = "A janela do Rastreador de missões de masmorra."
L["The dungeons on whose ground the list shows. Contested ones and the raids are always listed. Also the switch beside the Journal's search."] = "As masmorras de qual território a lista mostra. As contestadas e as raides são sempre listadas. Também é o botão ao lado da busca do Diário."
L["The Edit Items window."] = "A janela Editar itens."
L["The extra gap between your aura and Righteous Fury and the class buttons."] = "O espaço extra entre sua aura e Fúria Virtuosa e os botões de classe."
L["The fastest way to any waypoint."] = "O caminho mais rápido até qualquer ponto de rota."
L["The first %d of %d; type more to narrow it down."] = "Os primeiros %d de %d; digite mais para refinar."
L["The first time someone speaks, ask their Naowh Forever for their zone with a hidden addon whisper. Players without it never see the question."] = "Na primeira vez que alguém fala, pergunta a zona ao Naowh Forever dessa pessoa com um sussurro oculto de addon. Jogadores sem ele nunca veem a pergunta."
L["The flight time to each destination when you hover it on the flight master's map."] = "O tempo de voo até cada destino quando você passa o mouse nele no mapa do mestre de voo."
L["The font for damage and healing numbers, over enemies and over your character. Off leaves the game's own font alone."] = "A fonte dos números de dano e cura, sobre inimigos e sobre seu personagem. Desligado mantém a fonte do jogo."
L["The font for the rest of the game: menus, chat, tooltips and names. Off leaves the game's own fonts alone."] = "A fonte do resto do jogo: menus, chat, dicas e nomes. Desligado mantém as fontes do jogo."
L["The font for this addon's windows and HUD. Font settings on a feature use it unless they pick their own. Saved for this computer.|n|nTakes effect after a /reload."] = "A fonte das janelas e do HUD deste addon. As configurações de fonte de um recurso a usam, a menos que escolham a própria. Salvo para este computador.|n|nTem efeito após um /reload."
L["The FPS / MS readout and the online counts on the buttons."] = "O FPS / MS e as contagens de online nos botões."
L["The FPS / MS readout stays up."] = "O FPS / MS continua visível."
L["The game does not name this fight yet: its kills count once the raid opens."] = "O jogo ainda não nomeia esta luta: os abates contam quando a raide abrir."
L["The game has no PvP rank for you yet. It shows once the season has started."] = "O jogo ainda não tem patente JxJ para você. Ela aparece quando a temporada começar."
L["The game has no route for %s, and its quest giver's spot is not known."] = "O jogo não tem rota para %s, e o local do PNJ de missão não é conhecido."
L["The game is not passing addon messages right now (in an encounter): ask again after it."] = "O jogo não está passando mensagens de addon agora (em um encontro): pergunte de novo depois."
L["The game lists no rank rewards for this season yet."] = "O jogo ainda não lista recompensas de patente para esta temporada."
L["The game would not disenchant this (skill too low?). Skipped until you reload."] = "O jogo não quis desencantar isto (perícia baixa demais?). Ignorado até você recarregar."
L["The game's own alert sounds first, then the addon's. Each plays as you pick it."] = "Os sons de alerta do próprio jogo primeiro, depois os do addon. Cada um toca quando você o escolhe."
L["The game's own look, in gold and bronze."] = "O visual do próprio jogo, em dourado e bronze."
L["The gap between the two."] = "O espaço entre os dois."
L["The gap between two buttons."] = "O espaço entre dois botões."
L["The Gear Sets window, with every set and what you can do with it."] = "A janela de Conjuntos de equipamento, com cada conjunto e o que você pode fazer com ele."
L["The group can be disbanded once the fight is over."] = "O grupo pode ser dissolvido depois que a luta acabar."
L["The group's paladins and the blessing each gives every class."] = "Os paladinos do grupo e a bênção que cada um dá a cada classe."
L["The guild name under a player's name."] = "O nome da guilda abaixo do nome de um jogador."
L["The highest rank this season"] = "A patente mais alta desta temporada"
L["The icon grows and shrinks with it."] = "O ícone cresce e encolhe junto."
L["The inspect window in the BiS List's look, with their score, gear check, talents and history."] = "A janela de inspeção no visual da Lista BiS, com a pontuação, a verificação de equipamento, os talentos e o histórico."
L["The item's cooldown sweeps over its icon."] = "A recarga do item gira sobre o ícone."
L["The item's quality"] = "A qualidade do item"
L["The item, your star and what happened, on screen for a while."] = "O item, sua estrela e o que aconteceu, na tela por um tempo."
L["The items the Buffs & Consumables reminders watch."] = "Os itens que os lembretes de Bônus e consumíveis monitoram."
L["The Journal beside the world map: bosses and loot in dungeons, factions outside."] = "O Diário ao lado do mapa-múndi: chefes e saque em masmorras, facções fora delas."
L["The Journal's own window."] = "A janela própria do Diário."
L["The key that changes Accept Quests, Hand In Quests, Pick Quests From NPCs and sharing."] = "A tecla que muda Aceitar missões, Entregar missões, Escolher missões dos PNJs e o compartilhamento."
L["The key that changes Auto Gossip for that NPC."] = "A tecla que muda Conversa automática para aquele PNJ."
L["The key that opens the BiS List."] = "A tecla que abre a Lista BiS."
L["The key that opens the Journal."] = "A tecla que abre o Diário."
L["The key that opens the Quest List window."] = "A tecla que abre a janela da Lista de missões."
L["The last %ds, scrolling %s%s"] = "Os últimos %ds, rolando %s%s"
L["The last fight's time stays on screen until the next one starts."] = "O tempo da última luta fica na tela até a próxima começar."
L["The last part of each melee swing, shaded."] = "A parte final de cada golpe corpo a corpo, sombreada."
L["the last profile cannot be deleted"] = "o último perfil não pode ser excluído"
L["The last profile cannot be deleted."] = "O último perfil não pode ser excluído."
L["The latest %d kills. First counted: %s."] = "Os últimos %d abates. Primeiro contado: %s."
L["The latest %d. First counted: %s."] = "Os últimos %d. Primeiro contado: %s."
L["The leader's zone on each Group Finder listing, and every member's zone when you hover it."] = "A zona do líder em cada anúncio do Localizador de Grupos, e a zona de cada membro quando você passa o mouse."
L["The level you are on as it runs, then completed levels, newest first."] = "O nível em que você está enquanto corre, depois os níveis concluídos, o mais novo primeiro."
L["The line round the bar."] = "A linha em volta da barra."
L["The list this character uses."] = "A lista que este personagem usa."
L["The longest a buff can last to show; longer ones like Arcane Intellect stay hidden."] = "A duração máxima de um bônus para aparecer; os mais longos, como Intelecto Arcano, ficam ocultos."
L["The macros the addon writes and keeps up to date for you, out of combat. Switch one on here, or take it to your bars from Smart Macros in Naowh's Forge."] = "As macros que o addon escreve e mantém atualizadas para você, fora de combate. Ligue uma aqui, ou leve-a às barras pelas Macros inteligentes na Naowh's Forge."
L["The macros you saved to the Forge's Library."] = "As macros que você salvou na Biblioteca da Forja."
L["The Man. The King."] = "O Cara. O Rei."
L["The map's window, the Journal beside the world map and Boss Loot at Cursor."] = "A janela do mapa, o Diário ao lado do mapa-múndi e o Saque do chefe no cursor."
L["The marks on the game's own character panel, as it looks (or EllesmereUI's), without the Naowh Character Panel. With it on, its slots have them already."] = "As marcas no painel de personagem do próprio jogo, como ele é (ou o do EllesmereUI), sem o Painel do personagem do Naowh. Com ele ligado, os espaços dele já as têm."
L["The Middle-click line."] = "A linha do clique do meio."
L["The most recent completed levels."] = "Os níveis concluídos mais recentes."
L["the name is empty"] = "o nome está vazio"
L["The name on it, and the community it is made for."] = "O nome nele, e a comunidade para a qual foi feito."
L["The Naowh Forever button on the minimap. The addon compartment entry and /naowh open this window either way."] = "O botão do Naowh Forever no minimapa. A entrada no compartimento de addons e /naowh abrem esta janela de qualquer forma."
L["The Naowh Forever N next to the name of Naowh, the developers, the moderators and our Legendary and Epic patrons in chat."] = "O N do Naowh Forever ao lado do nome do Naowh, dos desenvolvedores, dos moderadores e dos nossos patronos Lendários e Épicos no chat."
L["The newest line stays at the anchor; older lines stack in this direction."] = "A linha mais nova fica na âncora; as mais antigas empilham nesta direção."
L["The next one frees in "] = "A próxima libera em "
L["the next rank of %s (cap %d)"] = "a próxima patente de %s (limite %d)"
L["The number on each icon counts your bank as well as your bags."] = "O número em cada ícone conta o banco além das bolsas."
L["The order the points are taken in"] = "A ordem em que os pontos são pegos"
L["the pattern"] = "o molde"
L["The people and projects behind Naowh Forever."] = "As pessoas e os projetos por trás do Naowh Forever."
L["The picked boss's loot and abilities, under the map."] = "O saque e as habilidades do chefe escolhido, abaixo do mapa."
L["The planner's own window, and a mini bar to leave up while you level."] = "A janela própria do planejador, e uma minibarra para deixar aberta enquanto sobe de nível."
L["The player list opens after combat."] = "A lista de jogadores abre depois do combate."
L["The player's guild rank beside their guild name."] = "A patente de guilda do jogador ao lado do nome da guilda."
L["The point of the bar that attaches."] = "O ponto da barra que se prende."
L["The point of the frame it attaches to."] = "O ponto do quadro em que ela se prende."
L["The purchase failed."] = "A compra falhou."
L["The purchase failed; the price may have changed."] = "A compra falhou; o preço pode ter mudado."
L["The purchase failed; the price may have changed.|r"] = "A compra falhou; o preço pode ter mudado.|r"
L["The Quest List's own window. Drag its bottom right corner to size it."] = "A janela própria da Lista de missões. Arraste o canto inferior direito para redimensionar."
L["The quest tracker, and sharing dungeon quests with your group."] = "O rastreador de missões, e o compartilhamento de missões de masmorra com seu grupo."
L["The quests that reward a pick you do not have yet."] = "As missões que dão como recompensa uma escolha que você ainda não tem."
L["The quiz opens when you sit down at a campfire and closes when you stand up."] = "O quiz abre quando você se senta em uma fogueira e fecha quando você se levanta."
L["The raid marker Mark Focus puts on your focus."] = "O marcador de raide que Marcar foco coloca no seu foco."
L["the rank before"] = "a patente anterior"
L["The ready ring shows with GCD Sweep on."] = "O anel de pronto aparece com Varredura da RG ligada."
L["The reagents your known spells use, such as Arcane Powder, candles, seeds, Symbols of Kings and Flash Powder, matched to the highest rank you know."] = "Os reagentes que seus feitiços conhecidos usam, como Pó Arcano, velas, sementes, Símbolos dos Reis e Pó Fulgurante, conforme a patente mais alta que você conhece."
L["The red time left blinks, to catch your eye."] = "O tempo restante vermelho pisca, para chamar sua atenção."
L["The same required-level filter applies to every stack, not each item separately."] = "O mesmo filtro de nível exigido vale para cada pilha, não para cada item separado."
L["The same sets as the character sheet's: equip, save, rename or delete them in the Gear Sets window."] = "Os mesmos conjuntos da ficha do personagem: equipe, salve, renomeie ou exclua na janela de Conjuntos de equipamento."
L["The same with a Greater Blessing, for a class that shares one blessing, while you carry Symbols of Kings."] = "O mesmo com uma Bênção Maior, para uma classe que compartilha uma bênção, enquanto você carrega Símbolos dos Reis."
L["The seconds left when the time turns red; it turns yellow at twice that."] = "Os segundos restantes quando o tempo fica vermelho; fica amarelo no dobro disso."
L["The serializer libraries are missing from this build."] = "As bibliotecas de serialização estão faltando nesta versão."
L["The shape of Naowh's arrow."] = "A forma da seta do Naowh."
L["The share of what the items sell for that the suggested tip adds on top of paying back the crafter's own materials. At least 1s unless set to 0."] = "A parte do valor de venda dos itens que a gorjeta sugerida soma ao reembolso dos materiais do próprio artesão. Pelo menos 1p, a menos que seja 0."
L["The shortest time between two thanks to the same player."] = "O menor tempo entre dois agradecimentos ao mesmo jogador."
L["The Slot"] = "O espaço"
L["The slot it is for."] = "O espaço a que se destina."
L["The slots and stats only"] = "Só os espaços e atributos"
L["The space between Naowh's arrow and the text under it."] = "O espaço entre a seta do Naowh e o texto abaixo dela."
L["The spec your gear is weighed for. Automatic follows your talents: the tree with the most points (a druid's Feral is weighed for damage; pick Feral Tank for a bear)."] = "A especialização para a qual seu equipamento é avaliado. Automático segue seus talentos: a árvore com mais pontos (Feral de druida é avaliado para dano; escolha Feral Tank para urso)."
L["The spot ahead of you, 312 yards away."] = "O local à sua frente, a 312 metros."
L["The spot off to your right."] = "O local à sua direita."
L["The stat weights each spec starts with."] = "Os pesos de atributos com que cada especialização começa."
L["The stealthed text while you are in stealth, as well as the reminder when you are not."] = "O texto de furtividade enquanto você está furtivo, além do lembrete quando não está."
L["The step and distance text under RestedXP's waypoint arrow."] = "O texto de etapa e distância abaixo da seta de ponto de rota do RestedXP."
L["The string is damaged: copy it again in full."] = "O texto está danificado: copie de novo por inteiro."
L["The suggested tip pays back the crafter's materials plus %d%% of what the items sell for (of all the materials, for a recipe that makes no item), rounded, at least 1s. Set a tip of your own in the order list on the right. Change the share in the Professions settings."] = "A gorjeta sugerida reembolsa os materiais do artesão mais %d%% do valor de venda dos itens (de todos os materiais, para uma receita que não fabrica item), arredondado, pelo menos 1p. Defina sua própria gorjeta na lista do pedido à direita. Mude a porcentagem nas configurações de Profissões."
L["The swing timer needs WoW: Forever's own swing event."] = "O timer de ataque precisa do evento de golpe próprio do WoW: Forever."
L["The tag in the speaker's class color. Off, it is grey."] = "A etiqueta na cor da classe de quem fala. Desligado, fica cinza."
L["the talent above it"] = "o talento acima dele"
L["The talent builds you saved in the Training Planner."] = "As builds de talentos que você salvou no Planejador de treinamento."
L["The Team"] = "A equipe"
L["The text in the theme's accent color instead of gold."] = "O texto na cor de destaque do tema em vez de dourado."
L["The theme RestedXP uses: its own, or one of the Naowh themes."] = "O tema que o RestedXP usa: o próprio, ou um dos temas do Naowh."
L["The time between the two sides. Click it for the calendar (not with a gamepad)."] = "A hora entre os dois lados. Clique para o calendário (não com controle)."
L["The time left turns yellow, then red near the end, so you see crowd control about to break."] = "O tempo restante fica amarelo e depois vermelho perto do fim, para você ver o controle de grupo prestes a quebrar."
L["The time left, turning yellow, then red, as the camp runs down."] = "O tempo restante, ficando amarelo e depois vermelho, enquanto o acampamento acaba."
L["The tint on every button's icon: Naowh's own and any addon's."] = "O tom no ícone de cada botão: os do Naowh e os de qualquer addon."
L["The Training Planner's help while you level: a toast when you level up with spells to train, and a panel beside your class trainer."] = "A ajuda do Planejador de treinamento enquanto você sobe de nível: um aviso quando você sobe de nível com feitiços para treinar, e um painel ao lado do instrutor de classe."
L["The unit frame the bar is attached to, or UIParent for the screen."] = "O quadro de unidade em que a barra está presa, ou UIParent para a tela."
L["The weights"] = "Os pesos"
L["The weights for %s."] = "Os pesos de %s."
L["The window's border fades with it."] = "A borda da janela esmaece junto."
L["The word itself."] = "A palavra em si."
L["The world map's options and every pin on it: town pins (service NPCs for your faction), quests, rares and entrances. Also set from the button on the map."] = "As opções do mapa-múndi e cada marcador nele: marcadores de cidade (PNJs de serviço da sua facção), missões, raros e entradas. Também pelo botão no mapa."
L["The XP of completed quests, and their text."] = "A XP de missões concluídas, e o texto dela."
L["The XP of quests still in progress, as a faded segment after the completed ones."] = "A XP de missões ainda em andamento, como um segmento esmaecido depois das concluídas."
L["The XP of quests still in progress. By default the completed quests color, faded."] = "A XP de missões ainda em andamento. Por padrão a cor das missões concluídas, esmaecida."
L["The zone of whoever speaks in a chat channel, guild chat or a whisper, in front of their message. The game never says where a stranger is, so a player is tagged once they are in the Group Finder, your guild, your friends or your group, came up in a /who, or answered from their own copy of Naowh Forever. Their first message may come through untagged."] = "A zona de quem fala em um canal de chat, no chat da guilda ou num sussurro, na frente da mensagem. O jogo nunca diz onde um desconhecido está, então um jogador é marcado quando está no Localizador de Grupos, na sua guilda, nos seus amigos ou no seu grupo, apareceu num /who, ou respondeu pelo próprio Naowh Forever. A primeira mensagem pode chegar sem marca."
