L["What a point of each stat is worth to your spec."] = "Quanto vale um ponto de cada atributo para sua especialização."
L["What a saved set brings back when you import it. Sets are saved and imported from the Action Bars window, out of combat."] = "O que um conjunto salvo traz de volta quando você o importa. Conjuntos são salvos e importados pela janela de Barras de ação, fora de combate."
L["What a waypoint from the Discovery window or the tracker does."] = "O que faz um ponto de rota da janela de Descobertas ou do rastreador."
L["What a zone's page in the Quest List window lists."] = "O que a página de uma zona na janela da Lista de missões lista."
L["What a zone's page in the Quest List window lists. Kills count from when Discovery is on: Shift-click a rare there to tick off one you killed before."] = "O que a página de uma zona na janela da Lista de missões lista. Abates contam a partir de quando Descobertas está ligado: Shift+clique em um raro ali para marcar um que você matou antes."
L["What changed in recent builds."] = "O que mudou nas builds recentes."
L["WHAT COMES ACROSS"] = "O QUE VEM JUNTO"
L["What drops in every dungeon and raid."] = "O que cai em cada masmorra e raide."
L["What each line is worth, in gold, silver and copper."] = "Quanto cada linha vale, em ouro, prata e cobre."
L["What each stack is worth, in its largest coin, under its icon."] = "Quanto cada pilha vale, na maior moeda, abaixo do ícone."
L["What each stat is worth to your spec: change them as you like."] = "Quanto cada atributo vale para sua especialização: mude como quiser."
L["What each stat is worth to your spec: the BiS List's upgrade percents and enchants come from them. Change the weights in the Stat Weights window, from the scales on the BiS List's title bar."] = "Quanto cada atributo vale para sua especialização: as porcentagens de melhoria e os encantamentos da Lista BiS vêm deles. Mude os pesos na janela Pesos de atributos, pela balança na barra de título da Lista BiS."
L["What each stat is worth to your spec: the upgrade percents and enchants come from them. Set your own."] = "Quanto cada atributo vale para sua especialização: as porcentagens de melhoria e os encantamentos vêm deles. Defina os seus."
L["What Happened"] = "O que aconteceu"
L["What happens when you open a vendor. Both work whether or not the Restock Reminder is on."] = "O que acontece quando você abre um mercador. Os dois funcionam com o Lembrete de reabastecimento ligado ou não."
L["What It Lists"] = "O que lista"
L["What it lists"] = "O que lista"
L["What it puts on you: a buff, or an enchant on a weapon."] = "O que ele põe em você: um bônus, ou um encantamento em uma arma."
L["What it says while you are in stealth."] = "O que diz enquanto você está furtivo."
L["What it says while you are out of stealth."] = "O que diz enquanto você não está furtivo."
L["What it shows as you enter combat."] = "O que mostra quando você entra em combate."
L["What it shows as you leave combat."] = "O que mostra quando você sai de combate."
L["What Lines Show"] = "O que as linhas mostram"
L["What Naowh's profession window adds to each recipe: the ones you have not learned yet, your next rank, and how many of each reagent you have."] = "O que a janela de profissão do Naowh adiciona a cada receita: as que você ainda não aprendeu, sua próxima patente e quantos de cada reagente você tem."
L["What opens when a flight starts; Off hides the Games button."] = "O que abre quando um voo começa; Desligado oculta o botão Jogos."
L["What Rows Show"] = "O que as linhas mostram"
L["What shows while you know a find but track none."] = "O que aparece enquanto você conhece uma busca mas não rastreia nenhuma."
L["What the copy card has selected when it opens."] = "O que o cartão de cópia deixa selecionado ao abrir."
L["What the Journal lists on a boss. The same switches as the Filters icon on its title bar."] = "O que o Diário lista em um chefe. Os mesmos botões do ícone de Filtros na barra de título dele."
L["What the stack fetches at the auction house, from your last Scan Prices or TradeSkillMaster."] = "Quanto a pilha rende na casa de leilões, da sua última Verificação de preços ou do TradeSkillMaster."
L["What the whole stack sells for at a vendor, and each item's price."] = "Por quanto a pilha inteira vende no mercador, e o preço de cada item."
L["What to train at each level, and its cost."] = "O que treinar em cada nível, e quanto custa."
L["What you can train now and what each level brings."] = "O que você pode treinar agora e o que cada nível traz."
L["What you can train now, what each level brings and what it costs."] = "O que você pode treinar agora, o que cada nível traz e quanto custa."
L["What you pay the crafter for this craft, sent with the whisper. Filled in with the suggested tip; type your own as 2g 50s, 75s or 2.5 (gold). Empty it to go back to the suggestion."] = "O que você paga ao artesão por esta criação, enviado com o sussurro. Preenchido com a gorjeta sugerida; digite a sua como 2g 50s, 75s ou 2.5 (ouro). Esvazie para voltar à sugestão."
L["What you wear that takes a better enchant for your level."] = "O que você usa que aceita um encantamento melhor para seu nível."
L["What your target is doing in a fight: their short buffs and the crowd control on them."] = "O que seu alvo está fazendo em uma luta: os bônus curtos dele e o controle de grupo nele."
L["Wheel"] = "Roda"
L["Wheel on the rows"] = "Roda sobre as linhas"
L["Wheel: size. Right-click for more."] = "Roda: tamanho. Clique direito para mais."
L["Wheel: text size. Click a line to hide it. Right-click for more."] = "Roda: tamanho do texto. Clique em uma linha para ocultá-la. Clique direito para mais."
L["When"] = "Quando"
L["When a profession's skill is high enough for its next rank (Journeyman, Expert, Artisan), a banner under the skill bar and on its card in the overview says what it takes and who teaches it: the nearest trainer, book vendor or quest giver. Click Waypoint to mark them on your map. Reaching it also says so once in chat; /naowh profrank repeats that."] = "Quando a perícia de uma profissão é alta o bastante para a próxima patente (Artífice, Especialista, Artesão), um banner abaixo da barra de perícia e no cartão dela na visão geral diz o que é preciso e quem ensina: o instrutor, mercador de livros ou PNJ de missão mais próximo. Clique em Ponto de rota para marcá-los no mapa. Ao chegar lá, isso também é dito uma vez no chat; /naowh profrank repete."
L["When an item on your list is up for a roll or in the loot window, and again when it is yours. Move the on-screen alert in the HUD Editor."] = "Quando um item da sua lista está na rolagem ou na janela de saque, e de novo quando ele é seu. Mova o alerta na tela no Editor de HUD."
L["When an NPC offers several things, goes straight to a finished quest to hand in, or the first quest on offer. Works with the two options above."] = "Quando um PNJ oferece várias coisas, vai direto a uma missão concluída para entregar, ou à primeira missão oferecida. Funciona com as duas opções acima."
L["When it is up for a roll or drops."] = "Quando está na rolagem ou cai."
L["When it is yours."] = "Quando é seu."
L["When You Leave"] = "Ao sair"
L["When you level up with new spells to train, a toast says how many and what they cost, with buttons to open the planner and to put a waypoint on your nearest trainer. Move it in the HUD Editor."] = "Quando você sobe de nível com novos feitiços para treinar, um aviso diz quantos são e quanto custam, com botões para abrir o planejador e para colocar um ponto de rota no instrutor mais próximo. Mova no Editor de HUD."
L["When you log out, the set this character saved last is saved again with your bars, macros and keybinds as they are."] = "Quando você sai do jogo, o conjunto que este personagem salvou por último é salvo de novo com suas barras, macros e atalhos como estão."
L["When you reach a city or inn, a flashing list in the middle of the screen of what you are short on. It stays up until you have what you need or leave. Move it in the HUD Editor."] = "Quando você chega a uma cidade ou estalagem, uma lista piscando no meio da tela com o que está faltando. Ela fica até você ter o que precisa ou sair. Mova no Editor de HUD."
L["When You Reset"] = "Ao reiniciar"
L["Where"] = "Onde"
L["Where %s starts is not known."] = "Não se sabe onde %s começa."
L["Where do you want to start?"] = "Por onde você quer começar?"
L["Where it comes from is not recorded yet; try the Auction House."] = "A origem ainda não foi registrada; tente a Casa de Leilões."
L["Where It Drops"] = "Onde cai"
L["Where on the frame the bar sits."] = "Onde no quadro a barra fica."
L["Where to get them"] = "Onde conseguir"
L["Where your distance to pulling aggro and the entry count sit: under the bars, or between the title bar and the bars."] = "Onde ficam sua distância para puxar o aggro e a contagem de entradas: abaixo das barras, ou entre a barra de título e as barras."
L["Where your star sits: on the icon's corner, before the name, or hidden."] = "Onde fica sua estrela: no canto do ícone, antes do nome, ou oculta."
L["Where? on Whispers"] = "Onde? nos sussurros"
L["Whether a healthstone or a potion comes first."] = "Se a pedra de vida ou a poção vem primeiro."
L["Whether a new mark counts on every character or only this one."] = "Se uma nova marca vale para todos os personagens ou só para este."
L["Whether NF Food leaves drinks to NF Drink."] = "Se a NF Food deixa as bebidas para a NF Drink."
L["Which blessing you give this class: Might, Wisdom, Kings, Salvation or Light."] = "Qual bênção você dá a esta classe: Poder, Sabedoria, Reis, Salvação ou Luz."
L["Which crowd control shows, by ability: every rank, and the same spell from items and creatures."] = "Qual controle de grupo aparece, por habilidade: todas as patentes, e o mesmo feitiço vindo de itens e criaturas."
L["Which debuffs show beside crowd control: off until you light them."] = "Quais penalidades aparecem ao lado do controle de grupo: desligadas até você acendê-las."
L["Which guild and title lines show with players' names, saved by the game itself."] = "Quais linhas de guilda e título aparecem com os nomes dos jogadores, salvas pelo próprio jogo."
L["Which kinds of consumable Scan Bags adds and Ask to Add asks about."] = "Quais tipos de consumível Verificar bolsas adiciona e Perguntar para adicionar pergunta."
L["Which mana spells get the line."] = "Quais feitiços de mana ganham a linha."
L["Which modules do you want?"] = "Quais módulos você quer?"
L["Which of your picks alert: your BiS only, your top two, or every pick on your list."] = "Quais escolhas alertam: só seu BiS, suas duas primeiras, ou cada escolha da sua lista."
L["Which the macro uses first when you carry both: a healthstone or a healing potion."] = "O que a macro usa primeiro quando você carrega os dois: uma pedra de vida ou uma poção de cura."
L["While a merchant is open, a Buy button under the chosen recipe's reagents buys from them, in one click, every checked reagent they sell, such as Coarse Thread or Weak Flux, for as many crafts as you set beside it. The total cost shows beside the button; hover Buy for each reagent."] = "Com um mercador aberto, um botão Comprar abaixo dos reagentes da receita escolhida compra dele, em um clique, cada reagente marcado que ele vende, como Linha Grossa ou Fundente Fraco, para quantas criações você definir ao lado. O custo total aparece ao lado do botão; passe o mouse em Comprar para cada reagente."
L["While flying"] = "Voando"
L["While flying and at the campfire"] = "Voando e na fogueira"
L["While Heroic Strike, Cleave, Maul or Raptor Strike is queued, the melee bars take its color and name."] = "Enquanto Golpe Heroico, Clivar, Espancar ou Golpe do Raptor estiver na fila, as barras corpo a corpo ganham a cor e o nome dele."
L["While the auction house is open, a Buy button under the chosen recipe's reagents buys the materials for as many crafts as you set beside it: every checked reagent that vendors do not sell. Each one shows its price first and is only bought when you click Confirm."] = "Com a casa de leilões aberta, um botão Comprar abaixo dos reagentes da receita escolhida compra os materiais para quantas criações você definir ao lado: cada reagente marcado que mercadores não vendem. Cada um mostra o preço antes e só é comprado quando você clica em Confirmar."
L["While the auction house is open, a Search AH button next to the chosen recipe's name searches it for the item the recipe makes. Unlearned recipes also get Search Recipe, for the pattern, plans or manual that teaches it. Recipes that make no item, such as enchants, get no Search AH."] = "Com a casa de leilões aberta, um botão Buscar na CL ao lado do nome da receita escolhida busca lá o item que a receita fabrica. Receitas não aprendidas também ganham Buscar receita, para o molde, plano ou manual que a ensina. Receitas que não fabricam item, como encantamentos, não ganham Buscar na CL."
L["While the auction house is open, Shift-click a recipe or a reagent to search the auction house for the item: what the recipe makes, or the reagent. While you type in chat, Shift-click still links it."] = "Com a casa de leilões aberta, Shift+clique em uma receita ou reagente para buscar o item na casa de leilões: o que a receita fabrica, ou o reagente. Enquanto você digita no chat, Shift+clique ainda cria o link."
L["While the mouse is away, with Show On Mouseover on."] = "Enquanto o mouse está longe, com Mostrar ao passar o mouse ligado."
L["While you are in a group, shares each quest you accept from an NPC with the others, if the quest can be shared. A quest someone shared with you is not shared again. The Modifier as you accept keeps it to yourself."] = "Enquanto você está em grupo, compartilha cada missão que você aceita de um PNJ com os outros, se a missão puder ser compartilhada. Uma missão que alguém compartilhou com você não é compartilhada de novo. O Modificador ao aceitar a mantém só para você."
L["While you carry books, a pin on who takes them: your librarian, or the mage trainer."] = "Enquanto você carrega livros, um marcador em quem os recebe: seu bibliotecário, ou o instrutor de magos."
L["While you cast, mark where the cast ends on the Main Hand bar. It turns red when the cast will still be going as the swing comes due."] = "Enquanto você lança, marca onde o lançamento termina na barra da mão principal. Fica vermelho quando o lançamento ainda estiver em andamento na hora do golpe."
L["whisper"] = "sussurro"
L["Whisper "] = "Sussurrar "
L["Whisper Lines"] = "Linhas de sussurro"
L["Whisper your target"] = "Sussurrar ao seu alvo"
L["Whispers for "] = "Sussurros para "
L["Whispers thanks when a player gives you a class buff in the open world; turn friendly nameplates on so the game can name them."] = "Sussurra um agradecimento quando um jogador dá a você um bônus de classe no mundo aberto; ligue as placas de identificação aliadas para o jogo poder nomeá-lo."
L["White: exact, from their Naowh Forever. Grey: added up from their gear."] = "Branco: exato, do Naowh Forever deles. Cinza: somado pelo equipamento deles."
L["Who the cast is aimed at, in their class color."] = "Em quem o lançamento mira, na cor da classe."
L["Whoever holds aggro in one color."] = "Quem segura o aggro, em uma cor."
L["Whose ranking the picker shows. Each spec keeps its own picks on a list."] = "A classificação de quem o seletor mostra. Cada especialização tem as próprias escolhas em uma lista."
L["Wide kite"] = "Pipa larga"
L["Widen the swing and Auto Shot windows by your world latency, so they show when to press rather than when the server acts."] = "Alarga as janelas de golpe e de Disparo Automático pela sua latência de mundo, para que mostrem quando pressionar e não quando o servidor age."
L["Width"] = "Largura"
L["Width and Height"] = "Largura e altura"
L["Wild Lines"] = "Linhas de Selva"
