L["With Enchanting open, a Disenchant button at the top of the window opens a window of every item in your bags you can disenchant: green, blue and purple weapons and armor (or type /naowh disenchant). Right-click an item to keep it: it is never disenchanted, on any character, until you right-click it again. Disenchant All disenchants the rest one by one, one item per click, as the game asks a click for every disenchant. An item the game will not take (skill too low) is skipped until you reload. Closes when combat starts."] = "Com Encantamento aberto, um botão Desencantar no topo da janela abre uma janela com cada item nas suas bolsas que você pode desencantar: armas e armaduras verdes, azuis e roxas (ou digite /naowh disenchant). Clique direito em um item para mantê-lo: ele nunca é desencantado, em nenhum personagem, até você clicar direito de novo. Desencantar tudo desencanta o resto um por um, um item por clique, pois o jogo exige um clique para cada desencantamento. Um item que o jogo não aceita (perícia baixa demais) é ignorado até você recarregar. Fecha quando o combate começa."
L["With rested experience ahead of the fill."] = "Com experiência de descanso à frente do preenchimento."
L["With their badge"] = "Com o emblema deles"
L["With their badge and Naowh Score"] = "Com o emblema e o Naowh Score deles"
