L["Your BiS in your bags or bank: put it on."] = "Seu BiS nas bolsas ou no banco: equipe."
L["Your BiS list is empty"] = "Sua lista BiS está vazia"
L["Your BiS list now keeps a ranked list per slot. These did not fit: "] = "Sua lista BiS agora mantém uma classificação por espaço. Estes não couberam: "
L["Your BiS List's slot marks on the items in your bags: item level, your BiS's star, Forever's mark and the green arrow on an upgrade. In the game's bags or EllesmereUI's."] = "As marcas de espaço da sua Lista BiS nos itens das suas bolsas: nível de item, a estrela do seu BiS, a marca do Forever e a seta verde em uma melhoria. Nas bolsas do jogo ou nas do EllesmereUI."
L["Your BiS lists, for every class."] = "Suas listas BiS, para todas as classes."
L["Your BiS only"] = "Só seu BiS"
L["Your BiS you do not have yet: where to go next."] = "O BiS que você ainda não tem: para onde ir em seguida."
L["Your BiS's star on a slot, and Forever's mark on what is new in Forever."] = "A estrela do seu BiS em um espaço, e a marca do Forever no que é novo no Forever."
L["Your BiS, your second pick, and so on."] = "Seu BiS, sua segunda escolha e assim por diante."
L["Your buttons and a clock along the top."] = "Seus botões e um relógio ao longo do topo."
L["Your buttons on either side of an optional clock, with FPS and latency underneath."] = "Seus botões dos dois lados de um relógio opcional, com FPS e latência embaixo."
L["Your buttons on either side of an optional clock, with FPS and latency underneath. Arrange the buttons in the preview: drag one to move it, its x removes it, a side's + adds one. Move the bar in the HUD Editor."] = "Seus botões dos dois lados de um relógio opcional, com FPS e latência embaixo. Organize os botões na prévia: arraste um para movê-lo, o x dele o remove, o + de um lado adiciona um. Mova a barra no Editor de HUD."
L["Your camp's bonuses and time left on screen, and a reminder when Camp Benefits runs out."] = "Os bônus e o tempo restante do seu acampamento na tela, e um lembrete quando os Benefícios de Acampamento acabarem."
L["Your camp's bonuses by the icon, always or while you hover it."] = "Os bônus do seu acampamento junto ao ícone, sempre ou ao passar o mouse."
L["Your cap is %d.\nFirst do the quest %s%s|r (%sskill %d):"] = "Seu limite é %d.\nPrimeiro faça a missão %s%s|r (%sperícia %d):"
L["Your cap is %d.\nFirst read %s (needs skill %d):"] = "Seu limite é %d.\nPrimeiro leia %s (requer perícia %d):"
L["Your cap is %d.\nFirst train %s (%s, needs skill %d):"] = "Seu limite é %d.\nPrimeiro treine %s (%s, requer perícia %d):"
L["Your cast ends before the swing comes due."] = "Seu lançamento termina antes da hora do golpe."
L["Your cast will still be going as the swing comes due."] = "Seu lançamento ainda estará em andamento na hora do golpe."
L["Your casts and channels swept around the ring too."] = "Seus lançamentos e canalizações também giram em volta do anel."
L["Your character panel (C) in the BiS List's look: each slot with its marks, your stats for your spec, and your Naowh Score under your level. The game keeps the panel and everything it does. With EllesmereUI, turning this on turns its character panel off, and off turns it back on, after a reload."] = "Seu painel de personagem (C) no visual da Lista BiS: cada espaço com as marcas, seus atributos para sua especialização e seu Naowh Score abaixo do nível. O jogo mantém o painel e tudo o que ele faz. Com o EllesmereUI, ligar isto desliga o painel de personagem dele, e desligar o liga de novo, após recarregar."
L["Your Characters"] = "Seus personagens"
L["Your characters at level %d"] = "Seus personagens no nível %d"
L["Your characters at level %d (%s)"] = "Seus personagens no nível %d (%s)"
L["Your characters on this realm and faction, remembered across your account: what they hold on item tooltips, and help at the mailbox."] = "Seus personagens neste reino e facção, lembrados em toda a conta: o que eles têm nas dicas de itens, e ajuda na caixa de correio."
