L["Your equipment sets, the same ones the character sheet keeps."] = "Seus conjuntos de equipamento, os mesmos que a ficha do personagem guarda."
L["Your experience per hour on a small card, with time to level, played time, session length and recent level times. Hidden at max level. Hover it for Start, Pause and Reset (also /naowh xp start, pause or reset). Move it in the HUD Editor."] = "Sua experiência por hora em um cartãozinho, com tempo até o nível, tempo jogado, duração da sessão e tempos dos níveis recentes. Oculto no nível máximo. Passe o mouse para Iniciar, Pausar e Redefinir (também /naowh xp start, pause ou reset). Mova no Editor de HUD."
L["Your experience. Its left end is a darker shade."] = "Sua experiência. A ponta esquerda tem um tom mais escuro."
L["Your flight on a card: time left, the stops on a track, and the next stop."] = "Seu voo em um cartão: tempo restante, as paradas em uma trilha e a próxima parada."
L["Your focus target's casts on a bar of their own, colored by whether your interrupt is ready, with a tick where it comes off cooldown and a shield on casts you cannot interrupt. Your interrupt is the first you know of Pummel, Shield Bash, Kick, Counterspell, Earth Shock, Silence and Feral Charge. Move it in the HUD Editor."] = "Os lançamentos do seu foco em uma barra própria, colorida conforme sua interrupção esteja pronta, com uma marca de quando ela sai da recarga e um escudo nos lançamentos que você não pode interromper. Sua interrupção é a primeira que você conhece entre Esmurrar, Batida de Escudo, Chute, Contrafeitiço, Choque Terreno, Silêncio e Investida Feral. Mova no Editor de HUD."
L["Your focus's name, tinted by class, with their class icon above the panel."] = "O nome do seu foco, na cor da classe, com o ícone de classe acima do painel."
L["Your focus, set with NF Focus: their timers keep counting while you fight someone else."] = "Seu foco, definido com NF Focus: os timers dele continuam contando enquanto você luta com outro."
L["Your game macros, not the Smart Macros, as one string to share."] = "Suas macros do jogo, não as Macros inteligentes, como um texto para compartilhar."
L["Your global cooldown swept around the ring, and a ready ring once it is over."] = "Sua recarga global girando em volta do anel, e um anel de pronto quando ela termina."
