L["Your level, experience and percentage on one bar, with the XP of completed quests and rested experience drawn past the fill. Replaces Blizzard's experience bar while it is on. Move it in the HUD Editor. Ctrl + right-click the bar to reset the session time and XP/Hour."] = "Seu nível, experiência e porcentagem em uma barra, com a XP de missões concluídas e a experiência de descanso desenhadas além do preenchimento. Substitui a barra de experiência da Blizzard enquanto está ligada. Mova no Editor de HUD. Ctrl + clique direito na barra para redefinir o tempo de sessão e o XP/hora."
