L["Your recent casts as icons scrolling away from a point, with a bar underneath while you were casting or on the global cooldown. Gaps in the bar are time spent doing nothing. Move it in the HUD Editor."] = "Seus lançamentos recentes como ícones deslizando a partir de um ponto, com uma barra embaixo enquanto você lançava ou estava em recarga global. Vãos na barra são tempo sem fazer nada. Mova no Editor de HUD."
