L["Your two trinket slots, movable: left-click to use one, right-click to equip a trinket from your bags outside combat. Move it in the HUD Editor."] = "Seus dois espaços de berloque, móveis: clique esquerdo para usar um, clique direito para equipar um berloque das bolsas fora de combate. Mova no Editor de HUD."
